\label{lem:ub-easy}
    Let $n \in \mathbb{N}$ and let $\mu$ be a distribution on pairs of odd functions $f,g: \mathbb{R}^n \to \{\pm 1\}$.
    Then $K_G^{-1} \geq c_1(\mu) - \sum_{\textnormal{odd }m \geq 3} |c_m(\mu)|$.

\label{thm:duality}
    Let $\mathcal C\subseteq\ell_1$ be the set of sequences $c(\mu)$, where ${n}\in\mathbb{N}$ and $\mu$ ranges over distributions on pairs of odd functions $f,g:\mathbb{R}^{n}\to\{\pm1\}$.
    Let $\mathcal{Q} = \{q \in \ell_\infty: q_1 = 1, \forall m \in \mathbb{N}. \; |q_m| \leq 1, q_{2m} =0\}$. 
    Then $v_\infty(q) = \sup_{c \in \mathcal{C}} {\langle{c, q}\rangle}$ and
    \begin{equation}\label{eq:duality1}
        \frac{1}{K_G} = \sup \Big\{c_1 - \sum_{\textnormal{odd }m \geq 3} |c_m|: c \in {\mathcal{C}}\Big\} = \inf\{{v_\infty}(q): q \in \mathcal{Q}\}\,.
    \end{equation}
    Furthermore, the infimum over $q$ is attained.

\hspace{0.1cm}\label{cor:krivine-schemes}
\begin{enumerate}[label=(\roman*)]
    \item (Hermite projection games attain the lower bound \cite{raghavendra2009towards})\footnote{\cref{cor:krivine-schemes} strengthens \cite[Theorem 1.4]{raghavendra2009towards} by proving that the infimum over $q \in \mathcal{Q}$ is attained.} There is $Q = \sum_{\textnormal{odd }m\ge1}q_m \Pi_m^{(n)}$ such that $q_1 = 1$ and $\operatorname{SDP}(Q)/\operatorname{OPT}(Q) = K_G - o_{n}(1)$.
    \item  (Krivine schemes attain the upper bound \cite{naor2014krivine}) For every $\varepsilon>0$, there exist ${n}\in\mathbb{N}$ and a distribution $\mu$ on pairs of odd functions $f,g:\mathbb{R}^{n}\to\{-1,1\}$ such that \[ c_1(\mu)-\sum_{\substack{m\ge3\\m\textnormal{ odd}}}|c_m(\mu)| \ge\frac1{K_G+\varepsilon}.\]
\end{enumerate}

The assumptions on $\mu$ with $q_1 = 1, |q_m| \leq 1$ imply ${\langle{c(\mu), q}\rangle} = \sum_{i} c_i(\mu) q_i \geq K_G^{-1} - 2\varepsilon$.
    On the other hand,
    \begin{align*}
        \sum_{i}c_i(\mu) q_i &= \operatorname{\mathbb{E}}_{(f,g) \sim \mu} \sum_i q_i{\langle{\Pi_i f, \Pi_i g}\rangle} = \operatorname{\mathbb{E}}_{(f,g) \sim \mu} {\langle{f, Qg}\rangle}\,.
    \end{align*}
    We conclude that $\operatorname{\mathbb{E}}_{(f,g) \sim \mu} {\langle{f, Qg}\rangle} \geq K_G^{-1} - 2\varepsilon$.

\hspace{0.1cm}\label{cor:krivine-schemes-exact}
\begin{enumerate}[label=(\roman*)]
    \item There is an operator $Q = \sum_{\textnormal{odd }m \geq 1}q_m \Pi_m$ on $\overline{L_2}$ such that $q_1 = 1$
    and $\operatorname{SDP}(Q)/\operatorname{OPT}(Q) = K_G$.
    \item There is a distribution $\mu$ supported on odd functions $f,g \in \overline{L_2}, f(X), g(X) \in \{-1,1\}$ such that $H_\mu(t) = \frac{t}{K_G}$.
\end{enumerate}

\label{thm:reduction}
Suppose a finite family of closed intervals $I$ covers $[0,1]$,
each with dimension-independent parameters satisfying
\cref{eq:rotation-tail}, \cref{eq:matrix-comparisons}, and
\begin{align}
 F(M)&\le C\quad\text{for every feasible }M,\label{eq:one-dimensional}\\
 C+\max_{x\in\partial I}\Phi(x)&\le {v_*}
 =\frac{1000}{1773}-10^{-9}.
 \label{eq:endpoint}
\end{align}
Here $\partial I$ denotes the interval endpoints.
Then $v_{n}(q)\le {v_*}$ for every ${n}\ge1$, hence Theorem \ref{thm:lower}.

The coefficients of $H$ satisfy
\begin{equation}\label{eq:upper-certified-head}
 c_1-\sum_{m=2}^{681}|c_m|>0.5618773799453352.
\end{equation}

\label{head:claim-numerical}
There exist nonnegative rational numbers $\hat C[a,b]$, $a+b\le681$, with
\begin{equation}\label{head:joint-plane}
 \sum_{a+b\le681}|\hat C[a,b]-C_{\rm tr}[a,b]|
 \le6.078879564946870\cdot10^{-8}
\end{equation}
and
\begin{equation}\label{head:finite-margin}
\begin{aligned}
 &[t]\left(\sum_{i\in\{0,\ldots,13,15,16\}}\lambda_i
   \sum_{a+b\le681}\hat C[a,b]P_i(t)^a(-t)^b
   +\lambda_{14}H_{14}(t)+\sum_{i=17}^{31}\lambda_iH_i(t)\right)\\
 &\quad-\sum_{m=2}^{681}\left|[t^m]\left(
   \sum_{i\in\{0,\ldots,13,15,16\}}\lambda_i
   \sum_{a+b\le681}\hat C[a,b]P_i(t)^a(-t)^b
   +\lambda_{14}H_{14}(t)+\sum_{i=17}^{31}\lambda_iH_i(t)
   \right)\right|\\
 &\qquad>0.56187924796168130219.
\end{aligned}
\end{equation}

\label{head:claim-quadrature}
The quadratures in step 2 satisfy
\begin{equation}\label{head:outer-error}
\begin{aligned}
 &\left\|\left(
 \operatorname{\mathbb{E}}[F_{\rm tr}\psi_a(W)\psi_\alpha(X)]
 -\frac{2(-1)^{(a+|\alpha|-1)/2}}\pi
       \sum_{\nu=1}^{768}U_{a\nu}\prod_{j=1}^3B_{\alpha_j}(s_\nu)
 \right)_{\substack{a+|\alpha|\le681\\a+|\alpha|\ \text{odd}}}\right\|_2\\
 &\qquad<2.917598329143\cdot10^{-10}+8.228746\cdot10^{-18},
\end{aligned}
\end{equation}
and, for every $1\le\nu\le768$,
\begin{equation}\label{head:B-error}
 \|\hat B_{\nu\cdot}-B(s_\nu)\|_2<5.604655228362\cdot10^{-12}.
\end{equation}

\label{head:claim-arithmetic}
\begin{equation}\label{head:arithmetic-error}
 \sum_{\substack{a+b\le681\\a+b\ \mathrm{odd}}}
 \left|\hat C[a,b]-\frac4{\pi^2}
 \sum_{\nu,\mu=1}^{768}U_{a\nu}U_{a\mu}[z^b]
 \left(\sum_{j=0}^{681}\hat B_{\nu j}\hat B_{\mu j}z^j\right)^3\right|
 \le5.996940779766870\cdot10^{-8}.
\end{equation}

\label{other:lemma}
\begin{equation}\label{eq:upper-certified-nonadditive}
 \lambda_{14}\sum_{m>681}|[t^m]H_{14}(t)|
     +\sum_{i=17}^{31}\lambda_i\sum_{m>681}|[t^m]H_i(t)|
 <0.000003878150168295.
\end{equation}

Claims~\ref{other:claim-staircase} and~\ref{other:claim-hyperplane} give
\[
 \begin{aligned}
 &\lambda_{14}\sum_{m>681}|[t^m]H_{14}(t)|
 +\sum_{i=17}^{31}\lambda_i\sum_{m>681}|[t^m]H_i(t)|\\
 &\quad<(1.254728050780+2.623422117515)\cdot10^{-6}
 =0.000003878150168295.
 \end{aligned}
\]

\label{other:claim-staircase}
\begin{equation}\label{other:staircase-numeric}
 \lambda_{14}\sum_{m>681}|[t^m]H_{14}(t)|
 <1.254728050780\cdot10^{-6}<1.254729\cdot10^{-6}.
\end{equation}

The formulas for $J_j$ in \cref{head:hermite-integrals} follow from
\[
 \frac d{dx}\operatorname{erfc}(x/\sqrt2)=-2\phi(x),\qquad
 (\phi\operatorname{He}_{j-1})'=-\phi\operatorname{He}_j,\qquad
 \lim_{x\to\pm\infty}\phi(x)\operatorname{He}_{j-1}(x)=0\quad(j\ge1).
\]
Define $u_{ij}:=\operatorname{\mathbb{E}}[F_*(X_1,X_2)\operatorname{He}_i(X_1)\operatorname{He}_j(X_2)]$.
By \cref{root:odd-hermite}, $u_{ij}=0$ for $i+j$ even. On the strip
$k/256\le y<(k+1)/256$, the definition of $F_*$ gives
\[
 \begin{aligned}
 \int_{\mathbb R}F_*(x,y)\operatorname{He}_i(x)\phi(x)\,dx
 &=\mathbf1_{\{i=0\}}+2\sum_a(-1)^aJ_i(r_{k,a}),\\
 \int_{\mathbb R}\operatorname{sign}(x)\operatorname{He}_i(x)\phi(x)\,dx
 &=2\mathbf1_{\{i\text{ odd}\}}J_i(0).
 \end{aligned}
\]
For $i+j$ odd, symmetry and $F_*(x,y)=-\operatorname{sign}(x)$ for $y\ge8$ yield
\begin{align}
 u_{ij}
 &=2\int_0^\infty\int_{\mathbb R}
       F_*(x,y)\operatorname{He}_i(x)\operatorname{He}_j(y)\phi(x)\phi(y)\,dx\,dy\notag\\
 &=2\sum_{k=0}^{2047}
  \left(\mathbf1_{\{i=0\}}+2\sum_a(-1)^aJ_i(r_{k,a})\right)
       \left[J_j(k/256)-J_j((k+1)/256)\right]\notag\\
 &\quad-4\mathbf1_{\{i\text{ odd}\}}J_i(0)J_j(8).
 \label{other:staircase-moments}
\end{align}
By \cref{eq:upper-staircase-kernel} and Parseval,
\begin{equation}\label{other:staircase-kernel}
 \sum_{m>681}|[t^m]H_{14}(t)|
 \le\sum_{3i+5j>681}\frac{u_{ij}^2}{i!j!}
 =1-\sum_{3i+5j\le681}\frac{u_{ij}^2}{i!j!}.
\end{equation}
Evaluating \cref{other:staircase-moments} with $384$-bit interval
arithmetic gives
\[
 \begin{gathered}
 \#\{(i,j)\in\mathbb Z_{\ge0}^2:i+j\text{ odd},\ 3i+5j\le681\}=7843,\\
 \sum_{3i+5j\le681}\frac{u_{ij}^2}{i!j!}>0.9648417014661795,\qquad
 \lambda_{14}(1-0.9648417014661795)<1.254728050780\cdot10^{-6}.
 \end{gathered}
\]

\label{other:claim-hyperplane}
\begin{equation}\label{other:hyperplane-numeric}
 \sum_{i=17}^{31}\lambda_i\sum_{m>681}|[t^m]H_i(t)|
 <2.623422117515\cdot10^{-6}<2.623423\cdot10^{-6}.
\end{equation}

\label{other:rare-lemma}
\begin{equation}\label{eq:upper-certified-rare}
 \sum_{i=1}^{13}\lambda_i\sum_{m>681}|[t^m]H_i(t)|
                                  <0.000034097111321496.
\end{equation}

\label{heavy:lemma}
\begin{equation}\label{heavy:final-number}
 \sum_{m>681}\left|[t^m]\sum_{i\in\{0,15,16\}}\lambda_iH_i(t)\right|
 <0.000007875733380418.
\end{equation}

Define
\begin{equation}\label{heavy:cap-definition}
 \begin{aligned}
 \chi(u)&:=1-462u^6+1980u^7-3465u^8+3080u^9-1386u^{10}+252u^{11},\\
 \widetilde r(x)&:=
 \begin{cases}
 r(x),&|x|\le27/4,\\
 {\operatorname{sign}}(x)\displaystyle\left(r(27/4)+
 \int_0^{\min\{|x|-27/4,1/4\}}r'(27/4+u)\chi(4u)\,du\right),&|x|>27/4.
 \end{cases}
 \end{aligned}
\end{equation}
For $i\in\{0,15,16\}$ and real $t\in[-1,1]$, let
\[
 \widetilde F(w,x):={\operatorname{sign}}\!\left(w+\sum_{j=1}^3\widetilde r(x_j)\right),
 \qquad \widetilde H_i(t):=\operatorname{\mathbb{E}}[\widetilde F(W,X)\widetilde F(W',X')],
\]
where $(W,W'),(X_j,X'_j)$ are independent centered jointly Gaussian
pairs with unit marginal variances and
$\operatorname{\mathbb{E}}[WW']=P_i(t)$, $\operatorname{\mathbb{E}}[X_jX'_j]=-t$, $1\le j\le3$.
Set $\mathcal D:=t\,d/dt$ and
$\mathbb T:=\{t\in\mathbb{C}:|t|=1\}$, parametrized by $t=e^{{\mathrm{i}}\theta}$ with measure $d\theta/(2\pi)$.
\begin{heavyclaim}\label{heavy:claim-perturbation}
The function $\widetilde r$ is bounded and $C^6$, with
$\widetilde r^{(j)}(x)=0$ for $|x|>7$, $1\le j\le6$, and
\begin{equation}\label{heavy:weighted-perturbation}
 \sum_{m\ge0}\left|[t^m]\sum_{i\in\{0,15,16\}}
 \lambda_i(H_i-\widetilde H_i)\right|
 \le4\sqrt{{\Pr}(F\ne\widetilde F)}
 \sum_{i\in\{0,15,16\}}\lambda_i
 <8.769183\cdot10^{-7}.
\end{equation}
\end{heavyclaim}
\begin{heavyclaim}\label{heavy:claim-circle}
The Taylor series of each $\widetilde H_i$ converges absolutely and uniformly on $|t|\le1$,
its restriction to $\mathbb T$ is $C^4$, and
$d^4\widetilde H_i(e^{{\mathrm{i}}\theta})/d\theta^4
=\mathcal D^4\widetilde H_i(e^{{\mathrm{i}}\theta})$. Moreover,
\begin{equation}\label{heavy:combined-numerical}
 \frac{\left\|\mathcal D^4\sum_{i\in\{0,15,16\}}
 \lambda_i\widetilde H_i\right\|_{{L_2}(\mathbb T)}}{\sqrt{14\cdot681^7}}
 +4\sqrt{{\Pr}(F\ne\widetilde F)}
 \sum_{i\in\{0,15,16\}}\lambda_i
 <0.000007875733380418.
\end{equation}
\end{heavyclaim}
By Claim~\ref{heavy:claim-circle}, four integrations by parts and
Parseval give
\[
 \sum_{m\ge0}m^8\left|[t^m]\sum_{i\in\{0,15,16\}}
 \lambda_i\widetilde H_i\right|^2
 =\left\|\mathcal D^4\sum_{i\in\{0,15,16\}}
 \lambda_i\widetilde H_i\right\|_{{L_2}(\mathbb T)}^2.
\]
Oddness of $\widetilde r$ and \cref{root:odd-hermite} imply that
the even coefficients vanish. Thus Cauchy--Schwarz and
\[
 \sum_{\substack{m>681\\m\text{ odd}}}m^{-8}
 \le\frac12\int_{681}^\infty x^{-8}\,dx=(14\cdot681^7)^{-1}
\]
give
\[
 \sum_{m>681}\left|[t^m]\sum_{i\in\{0,15,16\}}
 \lambda_i\widetilde H_i\right|
 \le\frac{\left\|\mathcal D^4\sum_{i\in\{0,15,16\}}
 \lambda_i\widetilde H_i\right\|_{{L_2}(\mathbb T)}}{\sqrt{14\cdot681^7}}.
\]
Adding \cref{heavy:weighted-perturbation} and using
\cref{heavy:combined-numerical} proves the lemma.

\label{heavy:claim-perturbation}
The function $\widetilde r$ is bounded and $C^6$, with
$\widetilde r^{(j)}(x)=0$ for $|x|>7$, $1\le j\le6$, and
\begin{equation}\label{heavy:weighted-perturbation}
 \sum_{m\ge0}\left|[t^m]\sum_{i\in\{0,15,16\}}
 \lambda_i(H_i-\widetilde H_i)\right|
 \le4\sqrt{{\Pr}(F\ne\widetilde F)}
 \sum_{i\in\{0,15,16\}}\lambda_i
 <8.769183\cdot10^{-7}.
\end{equation}

\label{heavy:claim-circle}
The Taylor series of each $\widetilde H_i$ converges absolutely and uniformly on $|t|\le1$,
its restriction to $\mathbb T$ is $C^4$, and
$d^4\widetilde H_i(e^{{\mathrm{i}}\theta})/d\theta^4
=\mathcal D^4\widetilde H_i(e^{{\mathrm{i}}\theta})$. Moreover,
\begin{equation}\label{heavy:combined-numerical}
 \frac{\left\|\mathcal D^4\sum_{i\in\{0,15,16\}}
 \lambda_i\widetilde H_i\right\|_{{L_2}(\mathbb T)}}{\sqrt{14\cdot681^7}}
 +4\sqrt{{\Pr}(F\ne\widetilde F)}
 \sum_{i\in\{0,15,16\}}\lambda_i
 <0.000007875733380418.
\end{equation}

\label{heavy:claim-endpoint}
Each entry in \cref{heavy:T-definition} is a strict upper bound for $T_{j,l}$, and
\[
 \widetilde C[a,b]\ge0,\qquad\sum_{a,b}\widetilde C[a,b]=1,\qquad
 \widetilde H_i(t)=\sum_{a,b}\widetilde C[a,b]P_i(t)^a(-t)^b.
\]
This series defines the extension of $\widetilde H_i$ to complex $|t|\le1$.
For nonnegative integers $p,j$ and $0\le\rho<1$,
\begin{equation}\label{heavy:M-estimates}
 \begin{aligned}
 \sum_{a\ge p,b\ge0}(a)_p\rho^{a-p}\widetilde C[a,b]
 &\le\frac{2(2p-3)!!}{\pi(1-\rho^2)^{p-1/2}}&&(1\le p\le4),\\
 \sum_{a\ge p,b\ge j}(a)_p(b)_j\rho^{a-p}\widetilde C[a,b]
 &\le\left(\sum_{l=1}^j
 \sqrt{\frac{2T_{j,l}(2p+2l-3)!!}
 {\pi(1-\rho^2)^{p+l-1/2}}}\right)^2&&(j\ge1,\ p+j\le4).
 \end{aligned}
\end{equation}
For $i\in\{0,15,16\}$, $|t|=1$ and $|P_i(t)|<1$,
\begin{equation}\label{heavy:D4-endpoint}
 \begin{aligned}
 |\mathcal D^4\widetilde H_i(t)|\le{}&24
 \sum_{\substack{p,j\ge0\\1\le p+j\le4}}\frac1{p!j!}
 [z^4]\left(\sum_{h=1}^4\frac{|\mathcal D^hP_i(t)|}{h!}z^h\right)^p
 \left(\sum_{h=1}^4\frac{z^h}{h!}\right)^j\\
 &\quad\cdot\sum_{a\ge p,b\ge j}
 (a)_p(b)_j|P_i(t)|^{a-p}\widetilde C[a,b].
 \end{aligned}
\end{equation}
The series and its first four $\mathcal D$-derivatives converge uniformly
on $\{t:|t|\le1,\ |P_i(t)|\le\rho\}$ for every $0\le\rho<1$.
